import{_ as a}from"./chunks/prontera-north.9N94lC28.js";import{c as d,Q as l,j as r,m as e}from"./chunks/framework.BPKcPtvA.js";const q=JSON.parse('{"title":"赛季系统深度解析","description":"RO3赛季制系统详解，赛季重置规则、继承内容、通行证奖励全解析。","frontmatter":{"title":"赛季系统深度解析","description":"RO3赛季制系统详解，赛季重置规则、继承内容、通行证奖励全解析。","lastUpdated":true},"headers":[],"relativePath":"guide/season.md","filePath":"guide/season.md","lastUpdated":1780230058000}'),i={name:"guide/season.md"};function o(h,t,s,n,u,b){return l(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="赛季系统深度解析" tabindex="-1">赛季系统深度解析 <a class="header-anchor" href="#赛季系统深度解析" aria-label="Permalink to &quot;赛季系统深度解析&quot;">​</a></h1><p><img src="'+a+'" alt="RO3 普隆德拉北门"></p><p>赛季制是RO3最核心的设计之一，每赛季持续3-4个月，带来全新的游戏内容和挑战。</p><h2 id="赛季基本规则" tabindex="-1">赛季基本规则 <a class="header-anchor" href="#赛季基本规则" aria-label="Permalink to &quot;赛季基本规则&quot;">​</a></h2><h3 id="赛季周期" tabindex="-1">赛季周期 <a class="header-anchor" href="#赛季周期" aria-label="Permalink to &quot;赛季周期&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>内容</th></tr></thead><tbody><tr><td>赛季初</td><td>第1-2周</td><td>新赛季开启，等级重置/部分继承</td></tr><tr><td>赛季中</td><td>第3-10周</td><td>GVG赛季赛、限时活动</td></tr><tr><td>赛季末</td><td>第11-12周</td><td>赛季结算、奖励发放</td></tr><tr><td>休赛期</td><td>1-2周</td><td>短暂休整，下赛季预告</td></tr></tbody></table><h3 id="赛季重置内容" tabindex="-1">赛季重置内容 <a class="header-anchor" href="#赛季重置内容" aria-label="Permalink to &quot;赛季重置内容&quot;">​</a></h3><p>根据制作人YU在AMA中的回答，赛季制的重置规则如下：</p><p><strong>完全重置</strong>：</p><ul><li>角色等级（恢复到基础起点）</li><li>装备/道具（部分可能保留至收藏）</li></ul><p><strong>部分继承</strong>：</p><ul><li>外观/皮肤类道具</li><li>赛季成就/称号</li><li>部分特殊道具（需确认）</li></ul><p><strong>不会重置</strong>：</p><ul><li>账号绑定的外观收藏</li><li>成就系统中的永久记录</li></ul><h3 id="赛季特色" tabindex="-1">赛季特色 <a class="header-anchor" href="#赛季特色" aria-label="Permalink to &quot;赛季特色&quot;">​</a></h3><ol><li><strong>新职业BD</strong>：每个赛季可能推出新的职业玩法搭配</li><li><strong>全新地图</strong>：赛季更新同步推出新地图和副本</li><li><strong>GVG赛季赛</strong>：公会战积分重置，争夺赛季冠军</li><li><strong>限定奖励</strong>：赛季专属装备、外观、称号</li></ol><h2 id="赛季通行证-battle-pass" tabindex="-1">赛季通行证（Battle Pass） <a class="header-anchor" href="#赛季通行证-battle-pass" aria-label="Permalink to &quot;赛季通行证（Battle Pass）&quot;">​</a></h2><p>RO3的赛季通行证系统为玩家提供赛季期间的持续奖励。</p><h3 id="通行证等级" tabindex="-1">通行证等级 <a class="header-anchor" href="#通行证等级" aria-label="Permalink to &quot;通行证等级&quot;">​</a></h3><p>通行证通过完成赛季任务积累经验值升级：</p><table tabindex="0"><thead><tr><th>等级范围</th><th>所需经验</th><th>主要奖励</th></tr></thead><tbody><tr><td>1-20</td><td>每级100</td><td>药水、材料、基础外观</td></tr><tr><td>21-40</td><td>每级150</td><td>精炼材料、卡片</td></tr><tr><td>41-60</td><td>每级200</td><td>蓝装、赛季币</td></tr><tr><td>61-80</td><td>每级250</td><td>紫装、限定头饰</td></tr><tr><td>81-100</td><td>每级300</td><td>赛季限定毕业装备</td></tr></tbody></table><h3 id="免费-vs-付费" tabindex="-1">免费 vs 付费 <a class="header-anchor" href="#免费-vs-付费" aria-label="Permalink to &quot;免费 vs 付费&quot;">​</a></h3><table tabindex="0"><thead><tr><th>通行证类型</th><th>价格</th><th>奖励内容</th></tr></thead><tbody><tr><td>免费</td><td>0</td><td>基础奖励（约30%内容）</td></tr><tr><td>高级</td><td>约30-50 RMB</td><td>全部奖励（含限定外观）</td></tr></tbody></table><h3 id="每日-每周任务" tabindex="-1">每日/每周任务 <a class="header-anchor" href="#每日-每周任务" aria-label="Permalink to &quot;每日/每周任务&quot;">​</a></h3><p><strong>每日任务</strong>：</p><ul><li>击杀怪物（200只）</li><li>完成日常副本</li><li>参与GVG/竞技场</li></ul><p><strong>每周任务</strong>：</p><ul><li>赛季副本通关</li><li>MVP狩猎</li><li>公会贡献达标</li></ul><h2 id="赛季奖励" tabindex="-1">赛季奖励 <a class="header-anchor" href="#赛季奖励" aria-label="Permalink to &quot;赛季奖励&quot;">​</a></h2><h3 id="段位奖励" tabindex="-1">段位奖励 <a class="header-anchor" href="#段位奖励" aria-label="Permalink to &quot;段位奖励&quot;">​</a></h3><p>根据赛季末的段位发放：</p><table tabindex="0"><thead><tr><th>段位</th><th>条件</th><th>奖励</th></tr></thead><tbody><tr><td>传说</td><td>排名前1%</td><td>传说称号+限定坐骑+大量赛季币</td></tr><tr><td>钻石</td><td>排名前10%</td><td>钻石称号+紫装+赛季币</td></tr><tr><td>黄金</td><td>排名前30%</td><td>黄金称号+蓝装+赛季币</td></tr><tr><td>白银</td><td>排名前60%</td><td>白银称号+材料</td></tr><tr><td>青铜</td><td>参与奖</td><td>参与称号</td></tr></tbody></table><h3 id="赛季币兑换" tabindex="-1">赛季币兑换 <a class="header-anchor" href="#赛季币兑换" aria-label="Permalink to &quot;赛季币兑换&quot;">​</a></h3><p>赛季币可兑换：</p><ul><li>赛季限定装备（错过不再有）</li><li>外观/头饰</li><li>精炼保护卷轴</li><li>卡片包</li></ul><h2 id="赛季策略建议" tabindex="-1">赛季策略建议 <a class="header-anchor" href="#赛季策略建议" aria-label="Permalink to &quot;赛季策略建议&quot;">​</a></h2><h3 id="赛季初-第1-2周" tabindex="-1">赛季初（第1-2周） <a class="header-anchor" href="#赛季初-第1-2周" aria-label="Permalink to &quot;赛季初（第1-2周）&quot;">​</a></h3><ul><li>快速升级到新赛季的等级线</li><li>完成通行证任务积累等级</li><li>了解本赛季的BD环境变化</li></ul><h3 id="赛季中-第3-10周" tabindex="-1">赛季中（第3-10周） <a class="header-anchor" href="#赛季中-第3-10周" aria-label="Permalink to &quot;赛季中（第3-10周）&quot;">​</a></h3><ul><li>专注GVG赛季赛冲分</li><li>积累赛季币</li><li>打造赛季限定装备</li></ul><h3 id="赛季末-第11-12周" tabindex="-1">赛季末（第11-12周） <a class="header-anchor" href="#赛季末-第11-12周" aria-label="Permalink to &quot;赛季末（第11-12周）&quot;">​</a></h3><ul><li>冲刺段位</li><li>用完所有赛季币</li><li>准备下赛季资源</li></ul><blockquote><p><strong>核心提示</strong>：RO3的赛季制鼓励玩家每个赛季尝试不同的职业和玩法，不必担心一步落后步步落后。每个赛季都是全新的起点！</p></blockquote>',43)])])}const m=d(i,[["render",o]]);export{q as __pageData,m as default};
